import{c as s,Q as n,j as p,m as e}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"算子动态库和静态库编译","description":"","frontmatter":{},"headers":[{"level":1,"title":"算子动态库和静态库编译","slug":"算子动态库和静态库编译"},{"level":2,"title":"算子库编译","slug":"算子库编译"},{"level":2,"title":"算子库集成和使用","slug":"算子库集成和使用"}],"relativePath":"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/算子动态库和静态库编译.md","filePath":"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/算子动态库和静态库编译.md"}'),l={name:"guide/编程指南/高级编程/高级特性/Aclnn算子工程化开发/算子动态库和静态库编译.md"};function i(t,a,c,o,r,_){return n(),p("div",null,[...a[0]||(a[0]=[e(`<h1 id="算子动态库和静态库编译" tabindex="-1">算子动态库和静态库编译 <a class="header-anchor" href="#算子动态库和静态库编译" aria-label="Permalink to &quot;算子动态库和静态库编译&quot;">​</a></h1><h2 id="算子库编译" tabindex="-1">算子库编译 <a class="header-anchor" href="#算子库编译" aria-label="Permalink to &quot;算子库编译&quot;">​</a></h2><p>算子动态库和静态库编译是将算子实现代码及相关文件编译为动态库和静态库的过程。相比自定义算子包编译，动态库和静态库编译能够显著简化集成与部署流程。该过程包括将算子Kernel实现、Host侧Tiling实现、<a href="./../算子入图开发/基本开发流程.html">入图适配文件</a>以及<a href="./单算子API调用.html">自动生成的单算子调用实现代码</a>编译链接成动态库和静态库。</p><p>同时会自动生成以下头文件：</p><ul><li>单算子调用aclnn头文件，用于<a href="./单算子API调用.html">单算子调用场景</a>；</li><li>算子原型定义头文件，用于<a href="./../算子入图开发/概述.html">算子入图场景</a>。</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>算子动态库和静态库编译支持如下型号：</p><ul><li>Ascend 950PR/Ascend 950DT</li><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li><li>Atlas 推理系列产品</li></ul></div><p>算子动态库和静态库编译的具体步骤如下：</p><ol><li><p>完成工程编译相关配置。</p><p>除了上文介绍的<a href="./算子包编译/算子工程编译.html">基础配置</a>，算子动态库和静态库编译需要在工程目录下的CMakePresets.json cacheVariables的配置项中配置ASCEND_PACK_SHARED_LIBRARY为True，默认为False（会生成run包）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;ASCEND_PACK_SHARED_LIBRARY&quot;: {</span></span>
<span class="line"><span>    &quot;type&quot;: &quot;BOOL&quot;,</span></span>
<span class="line"><span>    &quot;value&quot;: &quot;True&quot;</span></span>
<span class="line"><span> }</span></span></code></pre></div></li><li><p>在算子工程目录下执行如下命令，进行算子工程编译。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./build.sh</span></span></code></pre></div><p>编译成功后，会在<a href="./算子包编译/算子工程编译.html">\${CMAKE_INSTALL_PREFIX}</a>/op_api目录生成以下文件：</p><ul><li>算子原型定义头文件，用于算子入图场景，定义算子的原型。</li><li>单算子调用aclnn头文件，用于单算子调用场景，提供直接调用算子的接口。</li><li>动态库libcust_opapi.so，用于动态链接。</li><li>静态库lib\${vendor_name}.a，用于静态链接。</li><li>安装文件\${vendor_name}-config.cmake和\${vendor_name}-targets.cmake，方便开发者将多个厂商的算子动态库或静态库集成到一个公共的动态库中，其中\${vendor_name}是厂商名，也可以理解成同一个算子工程生成的算子package名称。具体集成方式可以参考<a href="#section15157027143410">算子库集成和使用</a>。</li></ul><p>具体目录结构如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>├── op_api</span></span>
<span class="line"><span>│   ├── include</span></span>
<span class="line"><span>│       ├── aclnn_optype1.h                  // 单算子调用aclnn头文件</span></span>
<span class="line"><span>│       └── aclnn_optype2.h</span></span>
<span class="line"><span>│       └── aclnn_optypexxx.h</span></span>
<span class="line"><span>│       └── op_proto.h                       // 算子原型定义头文件</span></span>
<span class="line"><span>│   ├── lib</span></span>
<span class="line"><span>│       ├── cmake</span></span>
<span class="line"><span>│         └── \${vendor_name}</span></span>
<span class="line"><span>│            ├──\${vendor_name}-config.cmake  // 安装文件，定义了项目中的配置选项和变量</span></span>
<span class="line"><span>│            └──\${vendor_name}-targets.cmake // 安装文件，定义静态库和动态库的构建目标\${vendor_name}::static和\${vendor_name}::shared，便于开发者使用静态库和动态库，自动处理库的依赖关系</span></span>
<span class="line"><span>│       ├── libcust_opapi.so                 // 算子动态库</span></span>
<span class="line"><span>│       └── lib\${vendor_name}.a              // 算子静态库</span></span></code></pre></div></li></ol><h2 id="算子库集成和使用" tabindex="-1">算子库集成和使用 <a class="header-anchor" href="#算子库集成和使用" aria-label="Permalink to &quot;算子库集成和使用&quot;">​</a></h2><ul><li><p>单算子调用场景</p><p>单算子调用场景可以通过如下方式对<a href="#section187261217143316">算子库编译</a>中生成的动态库和静态库进行集成和使用。</p><p>完整样例可参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/00_compilation/custom_op_static_lib" target="_blank" rel="noreferrer">静态库集成和使用样例</a>。</p><ul><li><p>动态库集成</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>find_package(\${vendor_name} REQUIRED     # \${vendor_name}为编译生成的算子package名称</span></span>
<span class="line"><span>    PATHS \${CUST_PKG_PATH}               # \${CUST_PKG_PATH}为编译生成的算子package的存放路径</span></span>
<span class="line"><span>    NO_DEFAULT_PATH</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>target_link_libraries(op_runner PRIVATE</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    \${vendor_name}::shared               # 已自动包含相关的target依赖</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>)</span></span></code></pre></div></li><li><p>静态库集成</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>find_package(\${vendor_name} REQUIRED     # \${vendor_name}为编译生成的算子package名称</span></span>
<span class="line"><span>    PATHS \${CUST_PKG_PATH}               # \${CUST_PKG_PATH}为编译生成的算子package的存放路径</span></span>
<span class="line"><span>    NO_DEFAULT_PATH</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>target_link_libraries(op_runner PRIVATE</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    \${vendor_name}::static                # 已自动包含相关的target依赖</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>)</span></span></code></pre></div></li><li><p>静态库和动态库混合使用场景</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>find_package(\${vendor_name1} REQUIRED     # \${vendor_name1}为编译生成的算子package名称</span></span>
<span class="line"><span>    PATHS \${CUST_PKG_PATH_1}              # \${CUST_PKG_PATH_1}为编译生成的算子package的存放路径</span></span>
<span class="line"><span>    NO_DEFAULT_PATH</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>find_package(\${vendor_name2} REQUIRED     # \${vendor_name2}为编译生成的算子package名称</span></span>
<span class="line"><span>    PATHS \${CUST_PKG_PATH_2}              # \${CUST_PKG_PATH_2}为编译生成的算子package的存放路径</span></span>
<span class="line"><span>    NO_DEFAULT_PATH</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>target_link_libraries(op_runner PRIVATE</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>    \${vendor_name1}::static                 # 已自动包含相关的静态库target依赖</span></span>
<span class="line"><span>    \${vendor_name2}::shared                 # 已自动包含相关的动态库target依赖</span></span>
<span class="line"><span>    ...</span></span>
<span class="line"><span>)</span></span></code></pre></div></li></ul></li></ul><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>上文中的算子package存放路径默认指算子工程<a href="./算子包编译/算子工程编译.html#li09452421512">\${CMAKE_INSTALL_PREFIX}</a>/op_api目录，开发者可以自行将op_api目录下的文件拷贝到自己的目录下，此时\${CUST_PKG_PATH}可以设置为该自定义目录。</li><li>由于不同算子工程生成的算子动态库名称相同，如果需要将多个动态库进行集成，需要对<strong>libcust_opapi.so</strong>名称进行修改： 编译前，修改op_host目录中的CMakeLists.txt文件，添加如下代码，设置不同的输出文件名，从而可以区分不同动态库。<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>set_target_properties(cust_opapi PROPERTIES</span></span>
<span class="line"><span>	OUTPUT_NAME \${vendor_name}</span></span>
<span class="line"><span>)</span></span></code></pre></div>编译后，修改生成的op_api目录中的\${vendor_name}-targets.cmake文件，将其中的<strong>libcust_opapi.so</strong>修改为lib\${vendor_name}.so。保证动态库名称的一致性。</li></ul></div><ul><li>算子入图场景 <ul><li><p>配置ASCEND_CUSTOM_OPP_PATH环境变量，将动态库libcust_opapi.so的绝对路径追加到该环境变量。由GE框架在图编译和执行时根据该环境变量搜索算子动态库并使用。环境变量位置越靠前，算子的优先级越高。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>export ASCEND_CUSTOM_OPP_PATH=\${CMAKE_INSTALL_PREFIX}/op_api/lib/:\${ASCEND_CUSTOM_OPP_PATH}</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>动态库编译和<a href="./算子包编译/算子工程编译.html">算子包编译</a>功能同时使用时，前者生成的动态库优先级更高。 如下示例中，path1和path3是算子包编译生成的目录，path2和path4是动态库编译产物的存放目录，则编译产物的优先级为2&gt;4&gt;1&gt;3。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ASCEND_CUSTOM_OPP_PATH=&lt;path1&gt;/vendor_name1:&lt;path2&gt;/op_api/lib/:&lt;path3&gt;/vendor_name3:&lt;path4&gt;/op_api/lib/</span></span></code></pre></div></div></li><li><p>如果开发者通过Ascend Graph进行图开发，除了配置环境变量的方式也可以采用直接在应用程序的编译文件中链接动态库libcust_opapi.so的方式。Ascend Graph图开发的相关信息请参考<a href="https://www.hiascend.com/document/redirect/CannCommunityGraphguide" target="_blank" rel="noreferrer">《图引擎开发指南》</a>。动态库链接方式的so加载优先级高于环境变量配置方式。</p></li></ul></li></ul>`,12)])])}const u=s(l,[["render",i]]);export{h as __pageData,u as default};
